text:
5 一个简单例子

palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })





















































































账面市值比与盈利价格比这两个特征，给每只股票各打一个分数。两组分数在股票之间的重叠度为 ρ，从 0（互不相关）到接近 1（完全一致）。模型只有一个载荷，是这两个特征的某种混合。投资者想要账面市值比倾向、又不想承担模型的因子暴露，于是分别用两把尺子剔除这个载荷。

试一试。（1）起始时 ρ = 0.6，载荷权重中盈利价格比占 0.75。载荷能复现账面市值比头寸的 57.6%。用普通尺子对冲，对冲后的头寸仍有 26.5% 落在载荷上；用特征尺子对冲则为 0.0%。（2）把 ρ 拖到 0：两种对冲都留下 0.0%。没有重叠时，两把尺子的结论一致。（3）把 ρ 拖到 0.9：普通尺子对冲后留下的部分升到 73.2%。（4）保持 ρ = 0.9，把盈利价格比所占的权重降到 0.10。载荷此时能复现目标头寸的 99.8%；特征尺子对冲后若要恢复倾向，头寸须放大到原来的约 517 倍。请留意：普通尺子看不到藏在股票里、而不在权重里的重叠；载荷能复现的目标越多，倾向就越难恢复。权重各占一半（0.50）时，普通尺子留下的部分恰好为零，这是因为本例中两个特征的地位对称；所以拖动权重时，留下的部分并不随之单调上升。本例只有一个载荷，也没有具体股票；论文的对冲每月作用于约 2,250 只股票，剔除所有估计出的载荷，并使净投资为零（表 I，第 10 页；式 11，第 24 页）。示意数字，并非论文数据。



图 1：示意例子，一个载荷，两把尺子。两个彼此重叠的特征；目标是账面市值比。


// Illustrative example (not paper data) for "A simple example" on the-ruler-matters pages (EN and ZH).
// Two standardised characteristics, 1 = book-to-market (the target) and 2 = earnings-to-price (the paper's own
// example, p. 3), whose stock scores overlap by rho: characteristic ruler Q = [[1, rho], [rho, 1]] (eq. 2, p. 3);
// the plain ruler is the identity. The model has one loading direction b with weights (1 - m, m), scaled to
// unit length under the plain ruler. Target a = (1, 0).
//   coverage (eq. 10, p. 21):                        C = (a'Qb)^2 / (a'Qa b'Qb)
//   plain-ruler hedge (coefficient orthogonality):   a_E = a - (a'b) b
//   characteristic-ruler hedge (eq. 11, p. 24; one loading, no cash column): a_Q = a - b (b'Qb)^-1 b'Qa
//   share of a hedged direction h still on the loading: (h'Qb)^2 / (h'Qh b'Qb); exactly 0 for a_Q
//   scale-up to restore the tilt along a_Q: 1 / (1 - C) (eq. 12, p. 28, with the residual-shape term set to 1)
viewof rt_rho = Inputs.range([0, 0.95], { value: 0.6, step: 0.05, label: LANG === "zh" ? "两个特征分数的重叠度 ρ" : "Overlap ρ of the two characteristics' scores" })







viewof rt_mix = Inputs.range([0.05, 0.95], { value: 0.75, step: 0.05, label: LANG === "zh" ? "载荷权重中盈利价格比所占比例" : "Share of the loading's weight on earnings-to-price" })







rt_calc = {
  const r = rt_rho, m = rt_mix
  const n = Math.hypot(1 - m, m), b = [(1 - m) / n, m / n], a = [1, 0]
  const q = (x, y) =&gt; x[0] * y[0] + x[1] * y[1] + r * (x[0] * y[1] + x[1] * y[0])   // characteristic ruler
  const e = (x, y) =&gt; x[0] * y[0] + x[1] * y[1]                                     // plain ruler
  const left = (h) =&gt; { const hh = q(h, h); return hh &lt; 1e-12 ? 0 : 100 * q(h, b) ** 2 / (hh * q(b, b)) }
  const C = q(a, b) ** 2 / (q(a, a) * q(b, b))
  const aE = [a[0] - e(a, b) * b[0], a[1] - e(a, b) * b[1]]
  const k = q(b, a) / q(b, b), aQ = [a[0] - k * b[0], a[1] - k * b[1]]
  const lq = left(aQ)
  return { cover: 100 * C, plain: left(aE), charac: lq &lt; 1e-9 ? 0 : lq, scale: 1 / (1 - C) }
}
rt_pct = (x) =&gt; `${x.toFixed(1)}%`
rt_scale = (x) =&gt; x &gt;= 100 ? Math.round(x).toLocaleString("en-GB") : x.toFixed(2)
rt_rows = [
  { label: LANG === "zh" ? "表示份额" : "Coverage", value: rt_calc.cover, fill: palette.rp_pca },
  { label: LANG === "zh" ? "普通尺子对冲" : "Plain-ruler hedge", value: rt_calc.plain, fill: palette.ipca },
  { label: LANG === "zh" ? "特征尺子对冲" : "Characteristic-ruler hedge", value: rt_calc.charac, fill: palette.qz_ipca }
]






























rt_chart = Plot.plot({
  width: Math.min(width, 640), height: 150, marginLeft: LANG === "zh" ? 100 : (width &lt; 520 ? 160 : 170), marginRight: width &lt; 520 ? 44 : 56, marginBottom: 40,
  style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: LANG === "zh" ? "图 1：同一个载荷，两把尺子下的对冲（示意）" : "Figure 1: One loading, a hedge under each ruler (illustrative)",
  ariaDescription: LANG === "zh"
    ? "三根横条：载荷能复现的账面市值比头寸份额；用普通尺子对冲后仍留在载荷上的份额；用特征尺子对冲后仍留在载荷上的份额（始终为零）。"
    : "Three bars: the share of the book-to-market position the loading reproduces; the share left on the loading after the plain-ruler hedge; and the share left after the characteristic-ruler hedge, which is always zero.",
  x: { domain: [0, 100], label: LANG === "zh" ? "占头寸的比例（%）" : "Share of the position (%)", grid: true },
  y: { label: null, domain: rt_rows.map((d) =&gt; d.label) },
  marks: [
    Plot.barX(rt_rows, { y: "label", x: "value", fill: "fill" }),
    Plot.text(rt_rows, { y: "label", x: "value", text: (d) =&gt; rt_pct(d.value), dx: 4, textAnchor: "start" }),
    Plot.ruleX([0])
  ]
})







rt_readout = {
  const c = rt_calc
  return html`&lt;p class="figcaption" style="font-size:14px;margin:.2rem 0 .4rem"&gt;${LANG === "zh"
    ? html`重叠度 ρ = ${rt_rho.toFixed(2)}，载荷权重中盈利价格比占 ${rt_mix.toFixed(2)}。载荷能复现账面市值比头寸的 &lt;strong&gt;${rt_pct(c.cover)}&lt;/strong&gt;。用普通尺子对冲，对冲后的头寸仍有 &lt;strong&gt;${rt_pct(c.plain)}&lt;/strong&gt; 落在载荷上；用特征尺子对冲则为 &lt;strong&gt;${rt_pct(c.charac)}&lt;/strong&gt;。特征尺子对冲后，要恢复原来的倾向，头寸须放大到原来的 &lt;strong&gt;${rt_scale(c.scale)}&lt;/strong&gt; 倍。`
    : html`Overlap ρ = ${rt_rho.toFixed(2)}; share of the loading's weight on earnings-to-price ${rt_mix.toFixed(2)}. The loading reproduces &lt;strong&gt;${rt_pct(c.cover)}&lt;/strong&gt; of the book-to-market position. After the plain-ruler hedge, &lt;strong&gt;${rt_pct(c.plain)}&lt;/strong&gt; of the hedged position still lies on the loading; after the characteristic-ruler hedge, &lt;strong&gt;${rt_pct(c.charac)}&lt;/strong&gt;. Restoring the original tilt after the characteristic-ruler hedge needs a position &lt;strong&gt;${rt_scale(c.scale)}&lt;/strong&gt; times its original size.`}&lt;/p&gt;`
}








这张示意图在浏览器中计算，需要启用 JavaScript。在起始取值（ρ = 0.6，载荷权重中盈利价格比占 0.75）下，载荷能复现账面市值比头寸的 57.6%；用普通尺子对冲，对冲后的头寸仍有 26.5% 落在载荷上，用特征尺子对冲则为 0.0%。



怎么读。表示份额是账面市值比头寸（按特征尺子下的平方大小计）中能由载荷复现的部分。两根对冲横条给出各自对冲后的头寸仍落在载荷上的比例。读数中的放大倍数为 1 ÷（1 − 表示份额），即论文头寸规模恒等式在第二项（剩余股票权重的形状）取 1 时的情形（式 12，第 28 页）。来源：按论文式 2、式 10 和式 11 在浏览器中计算的示意数字；无数据文件。


在论文的数据中，这一差距很大。在无约束截距、153 个特征的模型中，用普通尺子对冲，账面市值比头寸平均仍有 46.10% 留在模型的载荷上，动量头寸为 53.51%，大公司规模头寸为 65.13%；用特征尺子对冲则为 0.00（表 IA.2，第 63 页）。下面的图 4可以在两把尺子之间切换。

5 一个简单例子
两位裁缝各自报告自己的版型与客人身材差了多少。裁缝 B 报出的差距更小，可 B 量的是一位身材更标准的客人，两个版型穿在他身上都很合身。要比较版型本身，就得让两个版型分别去套两位客人，这就是论文的 2×2 交叉（A 为等权模型，B 为市值加权模型）。套在 A 的客人身上，两个版型不合身的程度相差无几（117.37 对 116.67 个基点）；套在 B 的客人身上，连 A 的版型也只差 75.02 个基点（表 1，第 13 页）。这里，版型是模型的因子，客人是预期收益估计，不合身的程度就是阿尔法。真正的客人谁也看不见：两位“客人”都只是对不可观测的预期收益的估计。所以，交叉比较只说明变的是哪一样，不说明哪份估计更对；要判断这一点，得看之后的收益。

试一试。 模型 A 的估计里含有一种个股层面的偏离，模型 A 的因子无法生成这种偏离；两个滑块调整的都是模型 B。示例打开时处于“情形 1”：先点“重置”，再依次点两个情形，留意右上和左下两格。


palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })























































































图 1：两个模型，两个阿尔法。五只股票、一个因子的示意数字；表格让每个模型的估计分别面对每个模型的因子。


// Preset stories (set both sliders at once). Story 1 is the default slider state.
pe_toy_presets = {
  const zh = LANG === "zh"
  const presets = [
    [zh ? "情形 1：B 换了估计" : "Story 1: B changed its estimate", 0.5, 0],
    [zh ? "情形 2：B 改进了因子" : "Story 2: B improved its factor", 1, 1],
    [zh ? "重置：两模型相同" : "Reset: identical models", 1, 0]
  ]
  const set = (input, x) =&gt; { input.value = x; input.dispatchEvent(new Event("input", { bubbles: true })) }
  const wrap = html`&lt;div role="group" aria-label="${zh ? "预设情形" : "Preset stories"}" style="display:flex;flex-wrap:wrap;gap:.4rem;margin:0 0 .6rem"&gt;&lt;/div&gt;`
  for (const [label, keep, tilt] of presets) {
    const b = html`&lt;button type="button" class="btn btn-sm btn-outline-secondary"&gt;${label}&lt;/button&gt;`
    b.onclick = () =&gt; { set(viewof pe_toy_keep, keep); set(viewof pe_toy_tilt, tilt) }
    wrap.append(b)
  }
  return wrap
}







viewof pe_toy_keep = Inputs.range([0, 1], { value: 0.5, step: 0.05, label: LANG === "zh" ? "B 的估计：保留 A 偏离的比例" : "B's estimate: share of A's tilt kept" })







viewof pe_toy_tilt = Inputs.range([0, 1], { value: 0, step: 0.05, label: LANG === "zh" ? "B 的因子：向该偏离倾斜的程度" : "B's factor: bend toward that tilt" })







pe_toy_stocks = [1, 2, 3, 4, 5]
pe_toy_stockName = (i) =&gt; LANG === "zh" ? `股票 ${i}` : `Stock ${i}`
pe_toy_betaA = [0.6, 0.9, 1.0, 1.2, 1.5]
pe_toy_premium = 0.5
pe_toy_extra = [0.40, -0.20, 0.10, -0.30, 0.25]
// At tilt = 1, B's exposures tilt fully toward A's stock-specific tilt, so one factor spans A's estimate
pe_toy_shift = pe_toy_extra.map((e) =&gt; 2 * e)
pe_toy_betaB = pe_toy_betaA.map((b, i) =&gt; b + pe_toy_tilt * pe_toy_shift[i])
pe_toy_meanA = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_extra[i])
pe_toy_meanB = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_keep * pe_toy_extra[i])
// Equal-stock projection of an estimate onto the span of one exposure vector
pe_toy_split = (beta, mean) =&gt; {
  const bb = beta.reduce((s, b) =&gt; s + b * b, 0), bm = beta.reduce((s, b, i) =&gt; s + b * mean[i], 0)
  const factor = beta.map((b) =&gt; b * bm / bb)
  return { factor, intercept: mean.map((m, i) =&gt; m - factor[i]) }
}
pe_toy_rms = (r) =&gt; 100 * Math.sqrt(r.reduce((s, x) =&gt; s + x * x, 0) / r.length)   // percent -&gt; basis points
pe_toy_cell = (beta, mean) =&gt; pe_toy_rms(pe_toy_split(beta, mean).intercept)
pe_toy_AA = pe_toy_cell(pe_toy_betaA, pe_toy_meanA)
pe_toy_BB = pe_toy_cell(pe_toy_betaB, pe_toy_meanB)
pe_toy_BA = pe_toy_cell(pe_toy_betaB, pe_toy_meanA)
pe_toy_AB = pe_toy_cell(pe_toy_betaA, pe_toy_meanB)
pe_toy_mA = LANG === "zh" ? "模型 A" : "Model A"
pe_toy_mB = LANG === "zh" ? "模型 B" : "Model B"
pe_toy_pF = LANG === "zh" ? "因子部分" : "Factor part"
pe_toy_pI = LANG === "zh" ? "阿尔法成分" : "Alpha component"
pe_toy_rows = [[pe_toy_mA, pe_toy_betaA, pe_toy_meanA], [pe_toy_mB, pe_toy_betaB, pe_toy_meanB]].flatMap(([m, beta, mean]) =&gt; {
  const s = pe_toy_split(beta, mean)
  return pe_toy_stocks.flatMap((st, i) =&gt; [
    { model: m, stock: st, part: pe_toy_pF, value: s.factor[i] },
    { model: m, stock: st, part: pe_toy_pI, value: s.intercept[i] }
  ])
})
pe_toy_totals = [[pe_toy_mA, pe_toy_meanA], [pe_toy_mB, pe_toy_meanB]].flatMap(([m, mean]) =&gt; pe_toy_stocks.map((st, i) =&gt; ({ model: m, stock: st, value: mean[i] })))




























































































































































pe_toy_chart = Plot.plot({
  width: Math.min(width, 760), height: 280, marginLeft: 50, marginTop: 36, marginBottom: 40, style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: LANG === "zh" ? "示意图：预期收益估计拆成因子部分与阿尔法成分" : "Illustrative example: expected-return estimates split into a factor part and an alpha component",
  ariaDescription: LANG === "zh" ? "两个模型下五只示意股票的堆叠柱状图；圆点标出每只股票的预期收益估计合计。" : "Stacked bars for five illustrative stocks under two models. Dots mark each stock's total expected-return estimate.",
  fx: { label: null },
  x: { label: LANG === "zh" ? "股票" : "Stock", axis: "bottom" },
  y: { label: LANG === "zh" ? "预期收益估计（每月 %）" : "Expected-return estimate (% per month)", grid: true },
  color: { domain: [pe_toy_pF, pe_toy_pI], range: [palette.complete, palette.qz_ipca], legend: true },
  marks: [
    Plot.ruleY([0], { stroke: palette.muted }),
    Plot.barY(pe_toy_rows, { fx: "model", x: "stock", y: "value", fill: "part", title: (d) =&gt; `${d.model}, ${pe_toy_stockName(d.stock)}\n${d.part}: ${d.value.toFixed(2)}%` }),
    Plot.dot(pe_toy_totals, { fx: "model", x: "stock", y: "value", fill: "white", stroke: "black", r: 3.5, title: (d) =&gt; `${d.model}, ${pe_toy_stockName(d.stock)}\n${LANG === "zh" ? "预期收益估计合计" : "Total estimate"}: ${d.value.toFixed(2)}%` })
  ]
