wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })





















































































打个比方。三个部门共用一间办公室，公司总利润是确定的；每个部门报出多少利润，取决于公共开支怎么分摊。换一种分摊规则，各部门的数字都会变，总数却不变，所以只看总数，永远选不出“对”的规则。这里的“部门”是潜在因子、可观测因子和截距，“公共开支”是选中同一批股票的特征之间的重叠部分。

试一试。 1. 把 ρ（两个价值信号的重叠度）调到 0，两把尺子一致。2. 把 ρ 拖到 0.9，潜在因子部分变大，可观测因子和截距部分变小，虚线标出的总数纹丝不动。原因是：可观测因子和截距的载荷都放在第二个信号上；第二个信号与账面市值比（潜在因子载荷所在的信号）重叠越多，特征尺子记在潜在因子名下的就越多。3. 切换到股票 B，有两部分是负数，而且 ρ 越大负得越多，总数却仍是 0.20。负值表示该来源被记为拉低了这只股票的拟合收益。请注意： 拟合本身告诉不了你哪根条形才对，决定拆分的只有尺子。



图 1：同一个拟合收益，两把尺子。示意例子（虚构数字，并非论文估计值）。


// Illustrative example (not paper data). Two characteristics, one latent factor, one
// observed factor and an intercept. The start is the plain-ruler section (identity metric); the
// characteristic ruler (Gram metric) M = [[1, rho], [rho, 1]] is applied with the matched
// transformation of Proposition 1 (paper eqs. 3.2-3.4). The fitted value z'h is identical under
// both rulers by construction: 1.00 for stock A and 0.20 for stock B.
viewof csm_toy_rho = Inputs.range([0, 0.95], { value: 0.4, step: 0.05, label: LANG === "zh" ? "两个价值信号的重叠度 ρ" : "Overlap ρ of the two value signals" })







viewof csm_toy_stock = Inputs.radio(new Map(LANG === "zh"
  ? [["股票 A：两个价值信号都高", "A"], ["股票 B：账面市值比高、另一个价值信号低", "B"]]
  : [["Stock A: high on both value signals", "A"], ["Stock B: high book-to-market, low second signal", "B"]]), { value: "A", label: LANG === "zh" ? "股票" : "Stock" })







csm_toy_split = (rho, z) =&gt; {
  // plain-ruler section: latent-factor loading on characteristic 1, retained loadings on characteristic 2
  const b = [1, 0], d = [0, 0.6], a = [0, 0.4], f = 1, g = 1
  const M = [[1, rho], [rho, 1]]
  const Mv = (x) =&gt; [M[0][0] * x[0] + M[0][1] * x[1], M[1][0] * x[0] + M[1][1] * x[1]]
  const dot = (x, y) =&gt; x[0] * y[0] + x[1] * y[1]
  const R = Math.sqrt(dot(b, Mv(b)))                  // eq. 3.2: normalize the latent loading
  const bM = b.map((x) =&gt; x / R)
  const cd = dot(bM, Mv(d)), ca = dot(bM, Mv(a))      // eq. 3.3: overlap of retained loadings with the latent span
  const dM = d.map((x, i) =&gt; x - bM[i] * cd), aM = a.map((x, i) =&gt; x - bM[i] * ca)
  const fM = R * f + cd * g + ca                      // eq. 3.4: offsetting factor adjustment
  return { latent: dot(z, bM) * fM, observed: dot(z, dM) * g, intercept: dot(z, aM), exposure: dot(aM, Mv(aM)) }
}
csm_toy_z = csm_toy_stock === "A" ? [0.5, 0.5] : [0.5, -0.3]
csm_toy_I = csm_toy_split(0, csm_toy_z)
csm_toy_G = csm_toy_split(csm_toy_rho, csm_toy_z)
csm_toy_parts = LANG === "zh"
  ? [["latent", "潜在因子"], ["observed", "可观测因子"], ["intercept", "截距"]]
  : [["latent", "Latent factor"], ["observed", "Observed factor"], ["intercept", "Intercept"]]
// Short axis labels (two lines); the table rows carry the full names.
csm_toy_rows = [[LANG === "zh" ? "普通尺子" : "Plain ruler", csm_toy_I], [LANG === "zh" ? `特征尺子\nρ = ${csm_toy_rho.toFixed(2)}` : `Characteristic ruler\nρ = ${csm_toy_rho.toFixed(2)}`, csm_toy_G]]
  .flatMap(([ruler, s]) =&gt; csm_toy_parts.map(([k, lab]) =&gt; ({ ruler, part: lab, value: s[k] })))












































csm_toy_chart = Plot.plot({
  width: Math.min(width, 640), height: 190, marginLeft: width &lt; 500 ? 120 : 150, marginRight: 20, marginBottom: 46, style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: LANG === "zh" ? "图 1：同一个拟合收益，两把尺子（示意）" : "Figure 1: One fitted return, two rulers (illustrative)",
  ariaDescription: LANG === "zh"
    ? "上下两根堆叠条形分别用普通尺子和特征尺子，把同一个拟合收益拆成潜在因子、可观测因子和截距三部分；两把尺子下的总数相同。"
    : "Stacked bars split the same fitted return into latent-factor, observed-factor and intercept parts under the plain ruler and under the characteristic ruler. The total is the same for both rulers.",
  x: { label: LANG === "zh" ? "对拟合收益的贡献（示意单位）" : "Contribution to the fitted return (illustrative units)", labelAnchor: width &lt; 500 ? "right" : "center", labelOffset: 40, grid: true },
  y: { label: null, domain: csm_toy_rows.map((d) =&gt; d.ruler).filter((v, i, a) =&gt; a.indexOf(v) === i) },
  color: { domain: csm_toy_parts.map((p) =&gt; p[1]), range: [palette.complete, palette.qz_ipca, palette.ipca], legend: true },
  marks: [
    Plot.barX(csm_toy_rows, Plot.stackX({ x: "value", y: "ruler", fill: "part", order: csm_toy_parts.map((p) =&gt; p[1]) })),
    Plot.ruleX([0], { stroke: palette.muted }),
    Plot.tickX([{ x: csm_toy_I.latent + csm_toy_I.observed + csm_toy_I.intercept }], { x: "x", stroke: "black", strokeWidth: 2, strokeDasharray: "4 2" }),
    Plot.tip(csm_toy_rows, Plot.pointerY(Plot.stackX({ x: "value", y: "ruler", title: (d) =&gt; `${d.ruler}\n${d.part}: ${fmt2(d.value)}` })))
  ]
})







csm_toy_table = {
  const zh = LANG === "zh"
  const r = (s) =&gt; ({ lat: fmt2(s.latent), obs: fmt2(s.observed), int: fmt2(s.intercept), tot: fmt2(s.latent + s.observed + s.intercept), exp: s.exposure.toFixed(3) })
  const I = r(csm_toy_I), G = r(csm_toy_G)
  return html`&lt;div class="table-scroll"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;${zh ? "潜在因子" : "Latent factor"}&lt;/th&gt;&lt;th&gt;${zh ? "可观测因子" : "Observed factor"}&lt;/th&gt;&lt;th&gt;${zh ? "截距" : "Intercept"}&lt;/th&gt;&lt;th&gt;${zh ? "拟合收益" : "Fitted return"}&lt;/th&gt;&lt;th&gt;${zh ? "截距承载量（平方）" : "How much the intercept carries (squared size)"}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;${zh ? "普通尺子（把两个信号视为互不相关）" : "Plain ruler (treats the two signals as unrelated)"}&lt;/td&gt;&lt;td&gt;${I.lat}&lt;/td&gt;&lt;td&gt;${I.obs}&lt;/td&gt;&lt;td&gt;${I.int}&lt;/td&gt;&lt;td&gt;&lt;strong&gt;${I.tot}&lt;/strong&gt;&lt;/td&gt;&lt;td&gt;${I.exp}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;${zh ? `特征尺子（按共同选中的股票计重叠，重叠度 ρ = ${csm_toy_rho.toFixed(2)}）` : `Characteristic ruler (counts shared stocks; overlap ρ = ${csm_toy_rho.toFixed(2)})`}&lt;/td&gt;&lt;td&gt;${G.lat}&lt;/td&gt;&lt;td&gt;${G.obs}&lt;/td&gt;&lt;td&gt;${G.int}&lt;/td&gt;&lt;td&gt;&lt;strong&gt;${G.tot}&lt;/strong&gt;&lt;/td&gt;&lt;td&gt;${G.exp}&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`
}







怎么读。上方条形用普通尺子（单位矩阵度量）拆分一只股票的拟合收益；下方条形用特征尺子（格拉姆度量），两个信号的重叠度为 ρ。虚线刻度标出拟合收益：无论用哪把尺子，股票 A 都是 1.00，股票 B 都是 0.20。表格最后一列对两只股票相同：它用各自的尺子衡量截距整体承载了多少，也就是截距上限所限制的量；即使某只股票的截距部分变大，这一列的数值仍可能变小。默认 ρ = 0.40 已经偏高：美国数据中重叠度的中位数为 0.06，二十对中仅一对超过 0.38（第 31 页）。来源：按论文命题 1 及式 3.2 至 3.4 的匹配变换计算的示意例子；无数据文件。


这个比方也有不同之处：特征尺子一旦选定，其取值由特征数据计算得出，所以尺子上的刻度，正是用你要量的同一批数据画出来的。
